#!/usr/bin/env python3
"""Validate all three handbook deliverables and their source fidelity."""

from __future__ import annotations

import difflib
import hashlib
from html.parser import HTMLParser
from pathlib import Path
import re
import subprocess
import sys


ROOT = Path(__file__).resolve().parents[1]
DIST = ROOT / "dist"
HTML = DIST / "project-handbook.html"
PDF = DIST / "project-handbook.pdf"
TEXT = DIST / "project-handbook.txt"
README_SOURCE = ROOT / "README.md"

HASHES = {
    "README.md": "f76e7ef4cb337e53b49f424ae79ff74a2ee902603f23bb7ad958874cf088b6ec",
    "assets/release-lifecycle.png": "4b8553e4dc7e306c2625f1a41f6ab4d637159582454daa82b5118d2fcf96ed7a",
    "assets/release-lifecycle.svg": "dca622b5610ef91dad88373fb840b8c639ae81ecca54ef5b60d5295c4b4db5dd",
    "assets/system-map.png": "b6b2113050d6c38a350bbb81e70aa0d32a573f86492705d5a6a9dbace8bb5b20",
    "assets/system-map.svg": "cec173117f2e9ce3fce23b9d7d50d8e0b25822cbfa06bc4f938f22f1e386071c",
}


class StructureParser(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.counts: dict[str, int] = {}
        self.images: list[str] = []
        self.resources: list[str] = []
        self.text: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        self.counts[tag] = self.counts.get(tag, 0) + 1
        values = dict(attrs)
        if tag == "img" and values.get("src"):
            self.images.append(values["src"] or "")
        if tag in {"img", "script", "link"}:
            target = values.get("src") or values.get("href")
            if target:
                self.resources.append(target)

    def handle_data(self, data: str) -> None:
        self.text.append(data)


def fail(message: str) -> None:
    print(f"FAIL: {message}")
    raise SystemExit(1)


def normalize(value: str) -> str:
    return " ".join(value.replace("\u00a0", " ").split())


def verify_sources() -> None:
    for relative, digest in HASHES.items():
        path = ROOT / relative
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != digest:
            fail(f"source document or local asset changed: {relative}")


def verify_html() -> None:
    if not HTML.is_file() or HTML.stat().st_size < 30_000:
        fail("missing or implausibly small dist/project-handbook.html")
    try:
        source = HTML.read_text(encoding="utf-8")
    except Exception as exc:
        fail(f"HTML is not UTF-8 text: {exc}")
    parser = StructureParser()
    parser.feed(source)

    if parser.counts.get("h1", 0) + parser.counts.get("h2", 0) < 18:
        fail("HTML did not preserve the heading hierarchy")
    for tag, minimum in {"table": 3, "ul": 3, "ol": 2, "blockquote": 1, "pre": 3, "img": 2}.items():
        if parser.counts.get(tag, 0) < minimum:
            fail(f"HTML did not preserve required {tag} structures")

    for resource in parser.resources:
        if resource.startswith(("http://", "https://", "//")):
            fail(f"HTML depends on a network resource: {resource[:80]}")
    if len(parser.images) != 2:
        fail("HTML must contain both local source images")
    for src in parser.images:
        if src.startswith("data:image/"):
            continue
        candidate = (HTML.parent / src).resolve()
        if not candidate.is_file() or ROOT not in candidate.parents:
            fail(f"HTML image is not available offline: {src}")

    visible = normalize(" ".join(parser.text))
    sequence = [
        "Executive summary", "1. Mission and service promise", "2. System boundaries and data flow",
        "3. Ownership and decision rights", "4. Request lifecycle", "5. Configuration and policy",
        "6. Release lifecycle", "7. Observability and alert design", "8. Incident command",
        "9. Degraded modes and recovery", "10. Capacity and regional planning",
        "11. Security and privacy operations", "12. Review, learning, and maintenance",
    ]
    positions = [visible.find(title) for title in sequence]
    if any(position < 0 for position in positions) or positions != sorted(positions):
        fail("HTML chapters are missing or out of source order")
    for literal in ("99.9%", "99.99%", "1.0%", "10.0%", "20.0%"):
        if literal not in visible:
            fail(f"HTML changed source numeric precision: {literal}")


def command_output(args: list[str]) -> str:
    try:
        proc = subprocess.run(args, text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30)
    except FileNotFoundError:
        fail(f"organizer dependency unavailable: {args[0]}")
    if proc.returncode != 0:
        fail(f"could not inspect PDF with {args[0]}: {proc.stderr.strip()}")
    return proc.stdout


def verify_pdf_and_text() -> None:
    if not PDF.is_file() or PDF.stat().st_size < 80_000 or not PDF.read_bytes().startswith(b"%PDF-"):
        fail("missing, invalid, or implausibly small dist/project-handbook.pdf")
    info = command_output(["pdfinfo", str(PDF)])
    match = re.search(r"^Pages:\s+(\d+)", info, re.MULTILINE)
    if not match or int(match.group(1)) < 7:
        fail("PDF must be a substantive multi-page handbook (at least seven pages)")
    images = command_output(["pdfimages", "-list", str(PDF)])
    image_rows = [line for line in images.splitlines() if re.match(r"\s*\d+\s+\d+\s+image\s+", line)]
    if len(image_rows) < 2:
        fail("PDF does not contain both handbook figures")

    extracted = command_output(["pdftotext", "-layout", str(PDF), "-"])
    normalized_extracted = normalize(extracted)
    if len(normalized_extracted) < 17_000:
        fail("PDF does not contain the complete selectable handbook text")
    for phrase in (
        "Atlas Operations Handbook", "Service ownership, release safety, and incident practice",
        "Executive summary", "Release evidence checklist", "Incident update template", "Glossary",
    ):
        if phrase not in normalized_extracted:
            fail(f"selectable PDF text is missing: {phrase}")

    if not TEXT.is_file() or TEXT.stat().st_size < 17_000:
        fail("missing or incomplete dist/project-handbook.txt")
    try:
        submitted = TEXT.read_text(encoding="utf-8")
    except Exception as exc:
        fail(f"extracted text is not UTF-8: {exc}")
    normalized_submitted = normalize(submitted)
    ratio = difflib.SequenceMatcher(None, normalized_extracted, normalized_submitted, autojunk=False).ratio()
    # A direct copy of README.md is deceptively similar to extracted text once
    # whitespace is collapsed.  Require a much closer match to the *actual PDF
    # text layer* and explicitly reject Markdown-source copies.
    if ratio < 0.99:
        fail(f"text output does not match text extracted from final PDF (similarity {ratio:.3f})")
    source_markdown = README_SOURCE.read_text(encoding="utf-8")
    source_ratio = difflib.SequenceMatcher(
        None, normalize(source_markdown), normalized_submitted, autojunk=False
    ).ratio()
    if source_ratio > 0.995 or "```" in submitted or re.search(r"!\[[^\]]*\]\([^\)]*\)", submitted):
        fail("text output appears to be copied from README.md rather than extracted from the final PDF")
    if TEXT.stat().st_mtime + 1 < PDF.stat().st_mtime:
        fail("text output predates the final PDF")


def main() -> None:
    verify_sources()
    verify_html()
    verify_pdf_and_text()
    print("PASS: offline HTML, illustrated PDF, and PDF-derived text preserve the handbook")


if __name__ == "__main__":
    main()
